import json, random, sys, subprocess, time, os

def mk_trace(tid, src, rows):
    return {"id": tid, "source": src, "rows": [{"t": i, "values": v} for i, v in enumerate(rows)]}

def scenario_eval_heavy(seed=7):
    """K=8, 20 atoms with quantifiers over deep bodies, max contexts."""
    rng = random.Random(seed)
    K = 8
    fields = [{"name": "n%d" % i, "type": "SIZE", "min": 0, "max": 1000} for i in range(4)]
    fields += [{"name": "c%d" % i, "type": "COUNT", "min": 0, "max": 100} for i in range(2)]
    fields += [{"name": "f%d" % i, "type": "FLAG"} for i in range(2)]
    fields += [{"name": "id0", "type": "ID", "values": ["a", "b", "c"]}]

    def deep_term(ty, depth, quant=True):
        if depth >= 4:
            return {"field": rng.choice([f["name"] for f in fields if f["type"] == ty]),
                    "at": "$" if (quant and rng.random() < 0.5) else rng.randrange(K)}
        kind = rng.choice(["add", "scale", "agg", "term"])
        if kind == "add":
            return {"add": [deep_term(ty, depth + 1, quant), deep_term(ty, depth + 1, quant)]}
        if kind == "scale":
            return {"scale": rng.randint(-8, 8), "term": deep_term(ty, depth + 1, quant)}
        if kind == "agg":
            f = rng.choice([f["name"] for f in fields if f["type"] == ty])
            a = rng.randrange(K); z = rng.randint(a, K - 1)
            return {"aggregate": rng.choice(["sum", "mean", "min", "max"]), "field": f,
                    "from": a, "to": z}
        return deep_term(ty, 4, quant)

    atoms = []
    for i in range(20):
        ty = rng.choice(["SIZE", "COUNT"])
        body = {"cmp": rng.choice(["le", "ge", "lt", "gt", "eq", "ne"]),
                "left": deep_term(ty, 1), "right": deep_term(ty, 1)}
        atoms.append({"quantifier": rng.choice(["any", "all"]), "from": 0, "to": K - 1,
                      "predicate": body})

    def rand_row():
        out = []
        for f in fields:
            if f["type"] == "FLAG": out.append(rng.random() < 0.6)
            elif f["type"] == "ID": out.append(rng.choice(f["values"]))
            else: out.append(rng.randint(f["min"], f["max"]))
        return out

    train = [mk_trace("tr%d" % i, "s%d" % (i % 16), [rand_row() for _ in range(258)])
             for i in range(16)]  # 16*(258-7)=4016 contexts
    probes = [mk_trace("pr0", "s0", [rand_row() for _ in range(128)])]
    queries = [mk_trace("q0", "s0", [rand_row() for _ in range(1024)])]
    return {"version": 1, "window": K, "schema": fields, "atoms": atoms,
            "policy": {"max_width": 3, "min_support": 2, "min_witness": 2},
            "train": train, "probes": probes, "queries": queries}

def scenario_mine_heavy(seed=11, p=0.8, natoms=20, nsrc=16, B=4, W=1, S=1):
    rng = random.Random(seed)
    K = 1
    fields = [{"name": "f%d" % i, "type": "FLAG"} for i in range(natoms)]
    atoms = [{"cmp": "eq", "left": {"field": "f%d" % i, "at": 0},
              "right": {"const": True, "type": "FLAG"}} for i in range(natoms)]

    def rand_row(bias=p):
        return [rng.random() < bias for _ in fields]

    per = 4096 // nsrc + K - 1
    train = [mk_trace("tr%d" % i, "s%d" % i, [rand_row() for _ in range(per)]) for i in range(nsrc)]
    probes = [mk_trace("pr0", "s0", [rand_row(0.5) for _ in range(128)])]
    queries = [mk_trace("q0", "s0", [rand_row(0.5) for _ in range(1024)])]
    return {"version": 1, "window": K, "schema": fields, "atoms": atoms,
            "policy": {"max_width": B, "min_support": S, "min_witness": W},
            "train": train, "probes": probes, "queries": queries}

if __name__ == "__main__":
    which = sys.argv[1]
    if which == 'eval':
        req = scenario_eval_heavy()
    elif which == 'mine':
        req = scenario_mine_heavy()
    elif which == 'mine2':
        req = scenario_mine_heavy(p=0.5, B=4, W=1)
    text = json.dumps(req)
    print('input bytes', len(text), file=sys.stderr)
    t0 = time.time()
    proc = subprocess.run(['/app/submission/run.sh'], input=text.encode(),
                          capture_output=True, cwd='/app/submission')
    el = time.time() - t0
    out = proc.stdout.decode()
    print('rc', proc.returncode, 'wall %.2fs' % el, 'stdout bytes', len(out))
    try:
        resp = json.loads(out)
        print('classes', len(resp.get('classes', [])), 'queries', len(resp.get('queries', [])),
              'members total', sum(c['members'] for c in resp.get('classes', [])))
        from collections import Counter
        print(Counter(q['status'] for q in resp.get('queries', [])))
    except Exception as e:
        print('bad out', out[:300], e)
    print('stderr', proc.stderr.decode()[:500])
